1	"use server";
2	
3	/**
4	 * Marks the whole inbox read.
5	 *
6	 * Owner D. Returns the number of rows touched so the bell badge can be updated
7	 * without a second round trip.
8	 *
9	 * Must call (do not reimplement): markAllNotificationsReadSchema, can,
10	 * getActor, toActionResult
11	 */
12	
13	import { ForbiddenActionError } from "@/actions/_lib/action-errors";
14	import { withAction } from "@/actions/_lib/with-action";
15	import { CACHE_PROFILES, revalidateTagged } from "@/lib/cache";
16	import { can } from "@/lib/permissions";
17	import { markAllNotificationsReadSchema } from "@/schemas/notification";
18	import { markAllRead } from "@/server/services/notification-service";
19	import type { ActionResult } from "@/types/api";
20	import type { OrgId } from "@/types/common";
21	
22	type MarkAllReadInput = { orgId: OrgId };
23	
24	const run = withAction<typeof markAllNotificationsReadSchema, number>(
25	  markAllNotificationsReadSchema,
26	  async (raw, actor) => {
