6	import { useCallback, useMemo, useSyncExternalStore } from "react";
7	import type { NotificationId, OrgId } from "@/types/common";
8	import type { Notification } from "@/types/notification";
9	import {
10	  EMPTY_NOTIFICATIONS,
11	  countUnread,
12	  getNotifications,
13	  markAllNotificationsRead,
14	  markNotificationRead,
15	  subscribeNotifications,
16	} from "./notification-store";
17	
18	export function useNotifications(orgId: OrgId): {
19	  notifications: readonly Notification[];
20	  unreadCount: number;
21	  markRead: (id: NotificationId) => void;
22	  markAllRead: () => void;
23	} {
24	  const read = useCallback(() => getNotifications(orgId), [orgId]);
25	  const notifications = useSyncExternalStore(
26	    subscribeNotifications,
27	    read,
28	    () => EMPTY_NOTIFICATIONS,
29	  );
30	
31	  const unreadCount = useMemo(
32	    () => countUnread(notifications),
33	    [notifications],
34	  );
