/**
 * Where a hit lands: an issue and a comment open their issue's page, a project
 * opens the project page. A subject that no longer resolves falls back to the
 * organization root rather than a link that goes nowhere.
 */
async function hrefFor(
  orgId: OrgId,
  orgSlug: string,
  kind: SearchSubjectKind,
  subjectId: string,
): Promise<string> {
  switch (kind) {
    case "issue":
      return issueHref(orgId, orgSlug, subjectId as IssueId);
    case "comment": {
      const comment = await commentRepo.findCommentById(
        orgId,
        subjectId as CommentId,
      );
      return comment === null
        ? orgPath(orgSlug)
        : issueHref(orgId, orgSlug, comment.issueId);
    }
    case "project": {
      const project = await projectRepo.findProjectById(
        orgId,
        subjectId as ProjectId,
      );
      return project === null
        ? orgPath(orgSlug)
        : projectPath(orgSlug, project.slug);
    }
  }
}

async function issueHref(
  orgId: OrgId,
  orgSlug: string,
  issueId: IssueId,
): Promise<string> {
  const issue = await issueRepo.findIssueById(orgId, issueId);
  if (issue === null) return orgPath(orgSlug);

  const project = await projectRepo.findProjectById(orgId, issue.projectId);
  if (project === null) return orgPath(orgSlug);

  return issuePath(orgSlug, project.slug, issue.number);
}

