import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/logger", async () => (await import("./server/_support/doubles/misc")).loggerModule);

import { emit } from "@/lib/event-bus";
import { PermissionDeniedError } from "@/lib/permissions";
import * as preferenceRepo from "@/server/repositories/notification-preference-repository";
import * as notificationRepo from "@/server/repositories/notification-repository";
import { registerEventHandlers } from "@/server/services/event-registry";
import * as commentService from "@/server/services/comment-service";
import * as issueService from "@/server/services/issue-service";
import * as notificationService from "@/server/services/notification-service";
import * as projectService from "@/server/services/project-service";
import * as searchService from "@/server/services/search-service";
import * as usageService from "@/server/services/usage-service";
import { createTenant, issueInput, useTemporaryDatabase } from "./server/_support/fixtures";
import type { Tenant } from "./server/_support/fixtures";
import type { CommentId, MemberId } from "@/types/common";
import type { Role } from "@/types/member";
import type { NotificationKind } from "@/types/notification";

let cleanup: () => void;
let tenant: Tenant;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  registerEventHandlers();
  tenant = await createTenant("verify", "free");
});

afterAll(() => {
  cleanup();
});

async function alertsFor(role: Role, kind?: NotificationKind) {
  const page = await notificationService.listNotifications(tenant.actors[role], {
    orgId: tenant.org.id,
    recipientId: tenant.userIds[role],
    unreadOnly: false,
    kind: kind === undefined ? undefined : [kind],
    limit: 100,
    cursor: null,
  });
  return page.items;
}

describe("personal inboxes", () => {
  it("refuses another member's inbox, mark-read and preference, whatever the role", async () => {
    const [row] = await notificationService.notify(
      tenant.org.id,
      "member_joined",
      [tenant.userIds.member],
      { title: "t", body: "b", href: "/x", actorId: null },
    );
    expect(row).toBeDefined();

    await expect(
      notificationService.listNotifications(tenant.actors.owner, {
        orgId: tenant.org.id,
        recipientId: tenant.userIds.member,
        unreadOnly: false,
        limit: 25,
        cursor: null,
      }),
    ).rejects.toBeInstanceOf(PermissionDeniedError);

    await expect(
      notificationService.markRead(tenant.actors.admin, {
        orgId: tenant.org.id,
        notificationId: row!.id,
      }),
    ).rejects.toBeInstanceOf(PermissionDeniedError);

    await expect(
      notificationService.updatePreference(tenant.actors.owner, {
        orgId: tenant.org.id,
        userId: tenant.userIds.member,
        kind: "issue_assigned",
        inApp: false,
        email: false,
        digestOnly: false,
      }),
    ).rejects.toBeInstanceOf(PermissionDeniedError);

    const own = await notificationService.markRead(tenant.actors.member, {
      orgId: tenant.org.id,
      notificationId: row!.id,
    });
    expect(own.readAt).not.toBeNull();
  });

  it("mark-all-read only touches the caller's own unread alerts", async () => {
    await notificationService.notify(tenant.org.id, "member_invited", [tenant.userIds.owner, tenant.userIds.viewer], {
      title: "t2",
      body: "b2",
      href: "/x",
      actorId: null,
    });
    const ownerBefore = await notificationRepo.countUnread(tenant.org.id, tenant.userIds.owner);
    expect(ownerBefore).toBeGreaterThan(0);

    const marked = await notificationService.markAllRead(tenant.actors.viewer, tenant.org.id);
    expect(marked).toBeGreaterThan(0);
    expect(await notificationRepo.countUnread(tenant.org.id, tenant.userIds.viewer)).toBe(0);
    expect(await notificationRepo.countUnread(tenant.org.id, tenant.userIds.owner)).toBe(ownerBefore);
  });

  it("hides alerts switched off for in-app, while keeping them for email", async () => {
    await preferenceRepo.upsertPreference({
      orgId: tenant.org.id,
      userId: tenant.userIds.viewer,
      kind: "issue_status_changed",
      inApp: false,
      email: true,
      digestOnly: false,
    });

    const issue = await issueService.createIssue(
      tenant.actors.owner,
      issueInput(tenant.org.id, tenant.project.id, {
        title: "Quiet status",
        assigneeId: tenant.userIds.viewer,
      }),
    );
    await issueService.changeIssueStatus(tenant.actors.owner, {
      orgId: tenant.org.id,
      issueId: issue.id,
      status: "in_progress",
    });

    expect(await alertsFor("viewer", "issue_status_changed")).toHaveLength(0);
    const unreadRows = await notificationRepo.listUnreadSince(
      tenant.org.id,
      tenant.userIds.viewer,
      "2000-01-01T00:00:00.000Z" as never,
    );
    const emailOnly = unreadRows.filter((row) => row.kind === "issue_status_changed");
    expect(emailOnly).toHaveLength(1);
    expect(emailOnly[0]?.channels).toEqual(["email"]);
  });
});

describe("fan-out", () => {
  it("tells the owner about a new member and not the member", async () => {
    const joiner = tenant.userIds.viewer;
    await emit("member.joined", {
      orgId: tenant.org.id,
      actorId: joiner,
      occurredAt: new Date().toISOString() as never,
      memberId: "mem-joined" as MemberId,
      userId: joiner,
      role: "viewer",
    });

    const owner = await alertsFor("owner", "member_joined");
    expect(owner.some((n) => n.href === `/${tenant.org.slug}/settings/members`)).toBe(true);
    expect(await alertsFor("viewer", "member_joined")).toHaveLength(0);
  });

  it("tells the assignee about status changes by others, and never about their own", async () => {
    const issue = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, {
        title: "Status watch",
        assigneeId: tenant.userIds.admin,
      }),
    );

    const assignedAlerts = await alertsFor("admin", "issue_assigned");
    expect(assignedAlerts.some((n) => n.href === `/${tenant.org.slug}/projects/platform/issues/${issue.number}`)).toBe(true);

    const before = (await alertsFor("admin", "issue_status_changed")).length;
    await issueService.changeIssueStatus(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: issue.id,
      status: "in_progress",
    });
    const afterOther = await alertsFor("admin", "issue_status_changed");
    expect(afterOther.length).toBe(before + 1);
    expect(afterOther[0]?.href).toBe(`/${tenant.org.slug}/projects/platform/issues/${issue.number}`);

    await issueService.changeIssueStatus(tenant.actors.admin, {
      orgId: tenant.org.id,
      issueId: issue.id,
      status: "done",
    });
    expect((await alertsFor("admin", "issue_status_changed")).length).toBe(before + 1);
  });

  it("sends nothing for an issue without an assignee, and no self-assignment alert", async () => {
    const countBefore = (await alertsFor("owner", "issue_status_changed")).length;
    const unassigned = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "Nobody home" }),
    );
    await issueService.changeIssueStatus(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: unassigned.id,
      status: "in_progress",
    });
    expect((await alertsFor("owner", "issue_status_changed")).length).toBe(countBefore);

    const selfAssigned = await issueService.createIssue(
      tenant.actors.admin,
      issueInput(tenant.org.id, tenant.project.id, {
        title: "Mine",
        assigneeId: tenant.userIds.admin,
      }),
    );
    expect(selfAssigned.assigneeId).toBe(tenant.userIds.admin);
    const adminAssigned = await alertsFor("admin", "issue_assigned");
    expect(adminAssigned.some((n) => n.href.endsWith(`/issues/${selfAssigned.number}`))).toBe(false);
  });

  it("links a comment mention to the issue page", async () => {
    const issue = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "Mention link" }),
    );
    await emit("comment.created", {
      orgId: tenant.org.id,
      actorId: tenant.userIds.member,
      occurredAt: new Date().toISOString() as never,
      commentId: "cmt-link" as CommentId,
      issueId: issue.id,
      mentionedUserIds: [tenant.userIds.owner],
    });
    const mentions = await alertsFor("owner", "comment_mention");
    expect(mentions.some((n) => n.href === `/${tenant.org.slug}/projects/platform/issues/${issue.number}`)).toBe(true);
  });
});

describe("plan-limit alerts", () => {
  it("tells the owner once per unread alert, even when a member tried", async () => {
    await projectService.createProject(tenant.actors.owner, {
      orgId: tenant.org.id,
      name: "Second",
      slug: "second",
      key: "SEC",
      description: null,
      visibility: "org",
      leadId: null,
      color: "#6366f1",
      targetDate: null,
    });

    const attempt = (role: Role) =>
      projectService
        .createProject(tenant.actors[role], {
          orgId: tenant.org.id,
          name: `Over ${role}`,
          slug: `over-${role}`,
          key: `OV${role.slice(0, 1).toUpperCase()}`,
          description: null,
          visibility: "org",
          leadId: null,
          color: "#6366f1",
          targetDate: null,
        })
        .catch(() => undefined);

    await attempt("owner");
    const first = await alertsFor("owner", "plan_limit_reached");
    expect(first).toHaveLength(1);
    expect(first[0]?.title).toBe("Plan limit reached for projects");
    expect(first[0]?.href).toBe(`/${tenant.org.slug}/settings/billing`);

    await attempt("member");
    expect(await alertsFor("owner", "plan_limit_reached")).toHaveLength(1);

    await notificationService.markRead(tenant.actors.owner, {
      orgId: tenant.org.id,
      notificationId: first[0]!.id,
    });
    await attempt("admin");
    expect(await alertsFor("owner", "plan_limit_reached")).toHaveLength(2);
  });

  it("does not alert on the periodic recount", async () => {
    const before = (await alertsFor("owner", "plan_limit_reached")).length;
    await usageService.recomputeUsage(tenant.org.id);
    expect((await alertsFor("owner", "plan_limit_reached")).length).toBe(before);
  });
});

describe("search hrefs", () => {
  it("links issue, comment and project hits to the pages the app serves", async () => {
    const issue = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "Zebra href probe" }),
    );
    const issueHits = await searchService.search(tenant.actors.member, {
      orgId: tenant.org.id,
      q: "Zebra href probe",
      kinds: ["issue"],
      limit: 25,
      cursor: null,
    });
    expect(issueHits.items[0]?.href).toBe(`/${tenant.org.slug}/projects/platform/issues/${issue.number}`);

    const comment = await commentService.createComment(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: issue.id,
      body: "Yankee href probe",
      parentId: null,
      mentionedUserIds: [],
    });
    const commentHits = await searchService.search(tenant.actors.member, {
      orgId: tenant.org.id,
      q: "Yankee href probe",
      kinds: ["comment"],
      limit: 25,
      cursor: null,
    });
    expect(commentHits.items[0]?.id).toBe(comment.id);
    expect(commentHits.items[0]?.href).toBe(`/${tenant.org.slug}/projects/platform/issues/${issue.number}`);

    const projectHits = await searchService.search(tenant.actors.member, {
      orgId: tenant.org.id,
      q: "Second",
      kinds: ["project"],
      limit: 25,
      cursor: null,
    });
    expect(projectHits.items[0]?.href).toBe(`/${tenant.org.slug}/projects/second`);
  });
});

