      digestOnly: false,
    });
    await notificationService.notify(tenant.org.id, "comment_created", [tenant.userIds.admin], {
      title: "email only",
      body: "b",
      href: "/x",
      actorId: null,
    });
    await preferenceRepo.upsertPreference({
      orgId: tenant.org.id,
      userId: tenant.userIds.admin,
      kind: "comment_created",
      inApp: true,
      email: true,
      digestOnly: false,
    });

    const everything = await alertsFor("admin");
